function endpointName(endpoint){return endpoint?.name||t('untitled');}
function anchor(endpoint,side){const isGroup=map.groups.some(g=>g.id===endpoint.id),w=isGroup?endpoint.w:238,h=isGroup?endpoint.h:(findNodeEl(endpoint.id)?.offsetHeight||nodeHeight(endpoint));return side==='left'?{x:endpoint.x,y:endpoint.y+h/2}:side==='right'?{x:endpoint.x+w,y:endpoint.y+h/2}:side==='top'?{x:endpoint.x+w/2,y:endpoint.y}:{x:endpoint.x+w/2,y:endpoint.y+h};}
const vector={left:{x:-1,y:0},right:{x:1,y:0},top:{x:0,y:-1},bottom:{x:0,y:1}};
function curve(a,b,fromPort,toPort){const d=Math.max(65,Math.min(230,Math.hypot(b.x-a.x,b.y-a.y)*.48)),va=vector[fromPort],vb=vector[toPort];const c1={x:a.x+va.x*d,y:a.y+va.y*d},c2={x:b.x+vb.x*d,y:b.y+vb.y*d};return{path:`M ${a.x} ${a.y} C ${c1.x} ${c1.y}, ${c2.x} ${c2.y}, ${b.x} ${b.y}`,x:(a.x+3*c1.x+3*c2.x+b.x)/8,y:(a.y+3*c1.y+3*c2.y+b.y)/8};}
function renderEdges(){const layer=$('edge-layer');layer.innerHTML='';if(!edgesVisible)return;visibleEdges().forEach(r=>{const a=endpointById(r.from),b=endpointById(r.to);if(!a||!b)return;const c=curve(anchor(a,r.fromPort),anchor(b,r.toPort),r.fromPort,r.toPort),g=document.createElementNS('http://www.w3.org/2000/svg','g');g.setAttribute('class','edge-group'+(selected?.type==='edge'&&selected.id===r.id?' selected':''));g.dataset.edge=r.id;g.innerHTML=`<path class="edge-line" d="${c.path}"/><path class="edge-hit" d="${c.path}" tabindex="0" role="button" aria-label="${esc(endpointName(a))} → ${esc(endpointName(b))}: ${esc(r.label||t('relation'))}"/><text class="edge-label" x="${c.x}" y="${c.y-10}" text-anchor="middle">${esc(r.label||r.kind)}</text>`;g.onclick=e=>{e.stopPropagation();selectItem('edge',r.id,true);};g.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();selectItem('edge',r.id,true);}};layer.append(g);});}
function selectItem(type,id,open=false){selected={type,id};if(open){document.body.classList.remove('inspector-hidden');document.body.classList.add('inspector-open');}document.querySelectorAll('.node').forEach(el=>el.classList.toggle('selected',type==='node'&&el.dataset.id===id));document.querySelectorAll('.group-box').forEach(el=>el.classList.toggle('selected',type==='group'&&el.dataset.group===id));renderEdges();renderInspector();}
function property(label,element){return `<label class="property"><span>${t(label)}</span>${element}</label>`;}
function renderInspector(){const panel=$('inspector-content');const node=selected?.type==='node'?map.entities.find(n=>n.id===selected.id):null,edge=selected?.type==='edge'?map.relationships.find(r=>r.id===selected.id):null,group=selected?.type==='group'?map.groups.find(g=>g.id===selected.id):null;
 if(node){const mod=moduleFor(node);panel.innerHTML=`<div class="inspector-banner" style="--module-color:${mod.color}"><span class="node-symbol">▤</span><div><strong>${esc(node.name)}</strong><small>${esc(mod.name)}</small></div></div>${property('name',`<input id="edit-name" value="${esc(node.name)}" maxlength="100" required>`)}${property('subtitle',`<input id="edit-label" value="${esc(node.label)}" maxlength="160">`)}${property('module',`<select id="edit-module">${map.modules.map(m=>`<option value="${esc(m.id)}" ${m.id===node.module?'selected':''}>${esc(m.name)}</option>`).join('')}</select>`)}${property('group',`<select id="edit-group"><option value="">${t('noGroup')}</option>${map.groups.map(g=>`<option value="${esc(g.id)}" ${g.id===node.groupId?'selected':''}>${esc(g.name)}</option>`).join('')}</select>`)}${property('description',`<textarea id="edit-description" maxlength="4000">${esc(node.description)}</textarea>`)}<div class="section-heading"><h3>${t('fields')} <span class="count-badge">${node.fields.length}</span></h3><button class="icon-button" id="add-field" aria-label="${t('addField')}" title="${t('addField')}">+</button></div><div id="inspector-fields">${node.fields.map((f,i)=>`<button class="inspector-field" data-index="${i}"><span class="field-key ${f.fk?'fk':''}">${f.pk?'PK':f.fk?'FK':'·'}</span><span class="field-name">${esc(f.name)}</span><span class="field-type">${esc(f.type)}</span></button>`).join('')||`<p class="inspector-note">${t('noFields')}</p>`}</div><div class="section-heading"><h3>${t('relationships')} <span class="count-badge">${map.relationships.filter(r=>r.from===node.id||r.to===node.id).length}</span></h3></div><div id="inspector-relations"></div><div class="inspector-actions"><button id="duplicate-node" class="outline">${t('duplicate')}</button><button id="delete-selected" class="quiet danger">${t('delete')}</button></div>`;
 ['name','label','description'].forEach(key=>$('edit-'+key).onchange=e=>{const value=e.target.value.trim();if(key==='name'&&!value){e.target.value=node.name;toast(t('emptyName'));return;}if(value!==node[key])commit(()=>node[key]=value);});$('edit-module').onchange=e=>{const value=e.target.value;commit(()=>{node.module=value;activeModules.add(value);});};$('edit-group').onchange=e=>{const value=e.target.value||null;commit(()=>{node.groupId=value;if(value)ensureNodeInsideGroup(node,map.groups.find(g=>g.id===value));});};$('add-field').onclick=()=>fieldDialog(node);$('inspector-fields').querySelectorAll('button').forEach(b=>b.onclick=()=>fieldDialog(node,Number(b.dataset.index)));$('duplicate-node').onclick=()=>duplicateSelected();$('delete-selected').onclick=deleteSelected;
 const rels=map.relationships.filter(r=>r.from===node.id||r.to===node.id);$('inspector-relations').innerHTML=rels.length?'':`<p class="inspector-note">${t('noRelations')}</p>`;rels.forEach(r=>{const other=endpointById(r.from===node.id?r.to:r.from);const b=document.createElement('button');b.className='relation-item';b.innerHTML=`<strong>${r.from===node.id?'→':'←'} ${esc(other?.name||'')}</strong><span>${esc(r.label||t('noLabel'))} · ${esc(r.kind)}</span>`;b.onclick=()=>selectItem('edge',r.id,true);$('inspector-relations').append(b);});
 }else if(edge){const from=endpointById(edge.from),to=endpointById(edge.to);panel.innerHTML=`<div class="inspector-banner"><span class="node-symbol" style="--module-color:var(--primary)">↗</span><div><strong>${t('relation')}</strong><small>${esc(endpointName(from))} → ${esc(endpointName(to))}</small></div></div>${property('relationName',`<input id="edit-edge-label" value="${esc(edge.label)}" maxlength="160" placeholder="${t('noLabel')}">`)}${property('cardinality',`<select id="edit-edge-kind">${[...new Set(['→','1:1','1:N','N:1','N:M',edge.kind])].map(k=>`<option ${edge.kind===k?'selected':''}>${esc(k)}</option>`).join('')}</select>`)}${property('from',`<input value="${esc(endpointName(from))} · ${t(edge.fromPort)}" readonly>`)}${property('to',`<input value="${esc(endpointName(to))} · ${t(edge.toPort)}" readonly>`)}<p class="inspector-note">${t('connectionHelp')}</p><div class="inspector-actions"><button id="delete-selected" class="outline danger">${t('delete')}</button></div>`;$('edit-edge-label').onchange=e=>{const value=e.target.value.trim();commit(()=>edge.label=value);};$('edit-edge-kind').onchange=e=>{const value=e.target.value;commit(()=>edge.kind=value);};$('delete-selected').onclick=deleteSelected;
 }else if(group){const members=map.entities.filter(n=>n.groupId===group.id);panel.innerHTML=`<div class="inspector-banner"><span class="node-symbol" style="--module-color:${group.color}">▦</span><div><strong>${esc(group.name)}</strong><small>${t('motherNode')} · ${members.length} ${t(members.length===1?'node':'nodes')}</small></div></div>${property('groupName',`<input id="edit-group-name" value="${esc(group.name)}" maxlength="100" required>`)}${property('color',`<input id="edit-group-color" type="color" value="${group.color}">`)}<button id="inspector-add-subnode" class="primary full">＋ ${t('addSubnode')}</button><div class="section-heading"><h3>${t('members')} <span class="count-badge">${members.length}</span></h3></div><div class="group-members">${map.entities.map(n=>`<label class="checkbox-row"><input type="checkbox" data-node="${esc(n.id)}"${n.groupId===group.id?' checked':''}>${esc(n.name)}</label>`).join('')||`<p class="inspector-note">${t('emptyGroup')}</p>`}</div><p class="inspector-note" style="margin-top:15px">${t('moveGroupHelp')}</p><div class="inspector-actions"><button id="delete-selected" class="outline danger">${t('removeMother')}</button></div><p class="inspector-note">${t('removeMotherHelp')}</p>`;$('edit-group-name').onchange=e=>{const value=e.target.value.trim();if(!value){e.target.value=group.name;return toast(t('emptyName'));}commit(()=>group.name=value);};$('edit-group-color').onchange=e=>{const value=e.target.value;commit(()=>group.color=value);};$('inspector-add-subnode').onclick=()=>newNodeInGroup(group.id);panel.querySelectorAll('[data-node]').forEach(input=>input.onchange=e=>{const n=map.entities.find(n=>n.id===e.target.dataset.node);commit(()=>{n.groupId=e.target.checked?group.id:null;if(e.target.checked)ensureNodeInsideGroup(n,group);});});$('delete-selected').onclick=deleteSelected;
 }else{panel.innerHTML=`<div class="empty-icon" style="margin-top:24px">▤</div><p class="inspector-note" style="text-align:center">${t('noSelection')}</p>`;}}
function updateTransform(){$('world').style.transform=`translate(${view.x}px,${view.y}px) scale(${view.z})`;$('zoom-level').textContent=Math.round(view.z*100)+'%';container.style.backgroundSize=`${20*view.z}px ${20*view.z}px`;container.style.backgroundPosition=`${view.x}px ${view.y}px`;}
function point(e){const rect=container.getBoundingClientRect();return{x:(e.clientX-rect.left-view.x)/view.z,y:(e.clientY-rect.top-view.y)/view.z};}
function ensureNodeInsideGroup(node,group){if(!group)return;group.w=Math.max(group.w,300);group.h=Math.max(group.h,nodeHeight(node)+80);node.x=Math.max(group.x+28,Math.min(node.x,group.x+group.w-266));node.y=Math.max(group.y+55,Math.min(node.y,group.y+group.h-nodeHeight(node)-25));}
function groupAtNode(node){const cx=node.x+119,cy=node.y+Math.min(nodeHeight(node),100)/2;return [...map.groups].reverse().find(g=>cx>=g.x&&cx<=g.x+g.w&&cy>=g.y+40&&cy<=g.y+g.h)||null;}
function zoomTo(z,cx=container.clientWidth/2,cy=container.clientHeight/2){z=Math.max(.15,Math.min(2.5,z));const ratio=z/view.z;view={x:cx-(cx-view.x)*ratio,y:cy-(cy-view.y)*ratio,z};updateTransform();}
function fit(){const nodes=visibleNodes(),groups=visibleGroups();if(!nodes.length&&!groups.length){view={x:0,y:0,z:1};updateTransform();return;}const bounds=[...nodes.map(n=>({x:n.x,y:n.y,w:238,h:findNodeEl(n.id)?.offsetHeight||nodeHeight(n)})),...groups.map(g=>({x:g.x,y:g.y,w:g.w,h:g.h}))];const minX=Math.min(...bounds.map(b=>b.x)),minY=Math.min(...bounds.map(b=>b.y)),maxX=Math.max(...bounds.map(b=>b.x+b.w)),maxY=Math.max(...bounds.map(b=>b.y+b.h));const w=container.clientWidth,h=container.clientHeight;const z=Math.max(.15,Math.min(1,(w-90)/(maxX-minX),(h-110)/(maxY-minY)));view={x:w/2-(minX+maxX)/2*z,y:(h-35)/2-(minY+maxY)/2*z,z};updateTransform();}
function newNode(at){if(map.entities.length>=1000)return toast(t('nodeLimit'));let id;commit(()=>{let module=map.modules.find(m=>activeModules.has(m.id))||map.modules[0];if(!module){module={id:M.uid(),name:t('general'),color:'#10b981',core:true};map.modules.push(module);}activeModules.add(module.id);const p=at||{x:(container.clientWidth/2-view.x)/view.z-119,y:(container.clientHeight/2-view.y)/view.z-65};id=M.uid();const n={id,module:module.id,name:t('untitled'),label:'',description:'',x:p.x,y:p.y,groupId:null,fields:[]};let tries=0;while(map.entities.some(other=>Math.abs(other.x-n.x)<20&&Math.abs(other.y-n.y)<20)&&tries++<25){n.x+=32;n.y+=32;}const group=groupAtNode(n);n.groupId=group?.id||null;if(group)ensureNodeInsideGroup(n,group);map.entities.push(n);selected={type:'node',id};});selectItem('node',id,true);$('edit-name').focus();$('edit-name').select();toast(t('created'));}
function newNodeInGroup(groupId,at){const group=map.groups.find(g=>g.id===groupId);if(!group)return;if(map.entities.length>=1000)return toast(t('nodeLimit'));let id;commit(()=>{let module=map.modules.find(m=>activeModules.has(m.id))||map.modules[0];if(!module){module={id:M.uid(),name:t('general'),color:'#10b981',core:true};map.modules.push(module);}activeModules.add(module.id);const cols=Math.max(1,Math.floor((group.w-55)/258)),index=map.entities.filter(n=>n.groupId===group.id).length,p=at||{x:group.x+28+(index%cols)*258,y:group.y+72+Math.floor(index/cols)*170};id=M.uid();const n={id,module:module.id,name:t('untitled'),label:'',description:'',x:p.x,y:p.y,groupId:group.id,fields:[]};ensureNodeInsideGroup(n,group);map.entities.push(n);selected={type:'node',id};});selectItem('node',id,true);$('edit-name').focus();$('edit-name').select();toast(t('created'));}
function deleteSelected(){if(!selected)return;const current={...selected};commit(()=>{if(current.type==='node')M.removeNode(map,current.id);else if(current.type==='group')M.removeGroup(map,current.id);else map.relationships=map.relationships.filter(r=>r.id!==current.id);selected=null;});cancelConnection();}
function duplicateSelected(){if(selected?.type!=='node')return;if(map.entities.length>=1000)return toast(t('nodeLimit'));commit(()=>{const n=M.duplicateNode(map,selected.id);if(n)selected={type:'node',id:n.id};});toast(t('copied'));}
function updateHint(){$('canvas-hint').textContent=t(pending?'connectHint':'hint');container.classList.toggle('connecting',!!pending);document.querySelectorAll('.port').forEach(p=>p.classList.toggle('pending',pending?.id===p.dataset.endpoint&&pending.side===p.dataset.port));}
function cancelConnection(){pending=null;$('draft-edge').hidden=true;document.querySelectorAll('.target').forEach(n=>n.classList.remove('target'));updateHint();}
function startConnection(id,side){pending={id,side};edgesVisible=true;$('edges-toggle').checked=true;renderEdges();updateHint();}
function finishConnection(id,side){if(!pending)return;try{if(map.relationships.length>=5000)throw new Error('edgeLimit');const before=JSON.stringify(map);const edge=M.connect(map,pending.id,pending.side,id,side);history.push(before);if(history.length>80)history.shift();future=[];cancelConnection();selected={type:'edge',id:edge.id};persist();render();selectItem('edge',edge.id,true);toast(t('connected'));}catch(e){toast(t(e.message));cancelConnection();}}
function handlePort(id,side){if(pending)finishConnection(id,side);else startConnection(id,side);}
function drawDraft(p){if(!pending)return;const endpoint=endpointById(pending.id);if(!endpoint)return cancelConnection();const opposite={left:'right',right:'left',top:'bottom',bottom:'top'};const c=curve(anchor(endpoint,pending.side),p,pending.side,opposite[pending.side]);$('draft-edge').setAttribute('d',c.path);$('draft-edge').hidden=false;}
container.addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==1)return;const port=e.target.closest('.port'),node=e.target.closest('.node'),groupEl=e.target.closest('.group-box');if(e.target.closest('.canvas-bottom,.tour-card,.empty-state,.edge-hit,.node-menu,.group-menu,.group-add-node'))return;e.preventDefault();if(port){const id=port.dataset.endpoint,side=port.dataset.port;if(pending){finishConnection(id,side);return;}startConnection(id,side);gesture={type:'connect',id:e.pointerId,startX:e.clientX,startY:e.clientY,moved:false};}else if(node&&e.button===0){cancelConnection();selectItem('node',node.dataset.id);const n=map.entities.find(n=>n.id===node.dataset.id);gesture={type:'node',id:e.pointerId,node:n,startX:e.clientX,startY:e.clientY,x:n.x,y:n.y,before:JSON.stringify(map),moved:false};}else if(groupEl&&e.button===0){cancelConnection();const group=map.groups.find(g=>g.id===groupEl.dataset.group);selectItem('group',group.id);if(e.target.closest('.group-resize'))gesture={type:'group-resize',id:e.pointerId,group,startX:e.clientX,startY:e.clientY,w:group.w,h:group.h,before:JSON.stringify(map),moved:false};else if(e.target.closest('.group-header'))gesture={type:'group',id:e.pointerId,group,startX:e.clientX,startY:e.clientY,x:group.x,y:group.y,members:map.entities.filter(n=>n.groupId===group.id).map(n=>({node:n,x:n.x,y:n.y})),before:JSON.stringify(map),moved:false};else return;}else{cancelConnection();selected=null;renderInspector();document.querySelectorAll('.node.selected,.group-box.selected').forEach(n=>n.classList.remove('selected'));renderEdges();gesture={type:'pan',id:e.pointerId,startX:e.clientX,startY:e.clientY,x:view.x,y:view.y,moved:false};container.classList.add('dragging');}container.setPointerCapture(e.pointerId);});
container.addEventListener('pointermove',e=>{if(pending)drawDraft(point(e));if(!gesture||e.pointerId!==gesture.id)return;const dx=e.clientX-gesture.startX,dy=e.clientY-gesture.startY;if(Math.hypot(dx,dy)>3)gesture.moved=true;if(!gesture.moved)return;if(gesture.type==='node'){gesture.node.x=gesture.x+dx/view.z;gesture.node.y=gesture.y+dy/view.z;const el=findNodeEl(gesture.node.id);el.style.left=gesture.node.x+'px';el.style.top=gesture.node.y+'px';document.querySelectorAll('.group-box').forEach(box=>box.classList.toggle('group-drop-target',groupAtNode(gesture.node)?.id===box.dataset.group));renderEdges();}else if(gesture.type==='group'){gesture.group.x=gesture.x+dx/view.z;gesture.group.y=gesture.y+dy/view.z;gesture.members.forEach(m=>{m.node.x=m.x+dx/view.z;m.node.y=m.y+dy/view.z;});renderGroups();gesture.members.forEach(m=>{const el=findNodeEl(m.node.id);if(el){el.style.left=m.node.x+'px';el.style.top=m.node.y+'px';}});renderEdges();}else if(gesture.type==='group-resize'){const members=map.entities.filter(n=>n.groupId===gesture.group.id),minW=Math.max(300,...members.map(n=>n.x+238-gesture.group.x+25)),minH=Math.max(180,...members.map(n=>n.y+nodeHeight(n)-gesture.group.y+25));gesture.group.w=Math.max(minW,Math.min(10000,gesture.w+dx/view.z));gesture.group.h=Math.max(minH,Math.min(10000,gesture.h+dy/view.z));renderGroups();}else if(gesture.type==='pan'){view.x=gesture.x+dx;view.y=gesture.y+dy;updateTransform();}else if(gesture.type==='connect'){const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('.port');document.querySelectorAll('.target').forEach(n=>n.classList.remove('target'));hit?.closest('.node,.group-box')?.classList.add('target');}});
function endGesture(e,cancelled=false){if(!gesture||e.pointerId!==gesture.id)return;const g=gesture;gesture=null;if(container.hasPointerCapture(e.pointerId))container.releasePointerCapture(e.pointerId);container.classList.remove('dragging');document.querySelectorAll('.group-drop-target').forEach(box=>box.classList.remove('group-drop-target'));if(g.type==='node'&&g.moved){if(cancelled){restore(g.before);}else{const target=groupAtNode(g.node);g.node.groupId=target?.id||null;if(target)ensureNodeInsideGroup(g.node,target);history.push(g.before);if(history.length>80)history.shift();future=[];persist();render();}}if((g.type==='group'||g.type==='group-resize')&&g.moved){if(cancelled)restore(g.before);else{history.push(g.before);if(history.length>80)history.shift();future=[];persist();render();}}if(g.type==='connect'){if(cancelled)return cancelConnection();const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('.port');if(g.moved&&hit)finishConnection(hit.dataset.endpoint,hit.dataset.port);else if(g.moved)cancelConnection();}}
container.addEventListener('pointerup',e=>endGesture(e));container.addEventListener('pointercancel',e=>endGesture(e,true));container.addEventListener('lostpointercapture',e=>{if(gesture)endGesture(e,true);});
container.addEventListener('dblclick',e=>{if(e.target.closest('.node,.edge-hit,.canvas-bottom,.tour-card,.empty-state,.group-header,.group-resize,.port'))return;const p=point(e),groupEl=e.target.closest('.group-box');if(groupEl)newNodeInGroup(groupEl.dataset.group,{x:p.x-119,y:p.y-45});else newNode({x:p.x-119,y:p.y-45});});
container.addEventListener('wheel',e=>{if(e.target.closest('.tour-card'))return;e.preventDefault();const r=container.getBoundingClientRect();zoomTo(view.z*Math.exp(-e.deltaY*.0012),e.clientX-r.left,e.clientY-r.top);},{passive:false});
function openDialog(title,body,action,submit=t('save')){cancelConnection();$('dialog-title').textContent=title;$('dialog-body').innerHTML=body;$('dialog-submit').textContent=submit;dialogAction=action;$('app-dialog').showModal();}
function closeDialog(){$('app-dialog').close();dialogAction=null;}
$('dialog-close').onclick=closeDialog;$('dialog-cancel').onclick=closeDialog;$('dialog-form').onsubmit=e=>{e.preventDefault();if(dialogAction?.()!==false)closeDialog();};
function moduleDialog(mod){if(!mod&&map.modules.length>=100)return toast(t('moduleLimit'));openDialog(t(mod?'editModule':'newModule'),`${property('moduleName',`<input id="module-name" maxlength="100" required value="${esc(mod?.name||'')}">`)}${property('color',`<input id="module-color" type="color" value="${mod?.color||'#10b981'}">`)}<label class="checkbox-row"><input id="module-core" type="checkbox" ${mod?.core?'checked':''}>${t('coreModule')}</label>`,()=>{const name=$('module-name').value.trim();if(!name){$('module-name').setCustomValidity(t('emptyName'));$('module-name').reportValidity();return false;}const color=$('module-color').value,core=$('module-core').checked;commit(()=>{if(mod)Object.assign(mod,{name,color,core});else{const m={id:M.uid(),name,color,core};map.modules.push(m);activeModules.add(m.id);}});});$('module-name').oninput=e=>e.target.setCustomValidity('');}
function groupDialog(){if(map.groups.length>=200)return toast(t('groupLimit'));const suggested=`${t('group')} ${map.groups.length+1}`,preselected=selected?.type==='node'?selected.id:null;openDialog(t('newGroup'),`${property('groupName',`<input id="group-name" maxlength="100" required value="${esc(suggested)}">`)}${property('color',`<input id="group-color" type="color" value="#5d8f79">`)}<p class="inspector-note" style="margin-bottom:10px">${t('chooseMembers')}</p><div class="group-members">${visibleNodes().map(n=>`<label class="checkbox-row"><input type="checkbox" data-group-node="${esc(n.id)}" ${n.id===preselected?'checked':''}>${esc(n.name)}</label>`).join('')||`<p class="inspector-note">${t('emptyGroup')}</p>`}</div>`,()=>{const name=$('group-name').value.trim();if(!name){toast(t('emptyName'));return false;}const ids=[...document.querySelectorAll('[data-group-node]:checked')].map(i=>i.dataset.groupNode),members=map.entities.filter(n=>ids.includes(n.id));let x,y,w,h;if(members.length){const minX=Math.min(...members.map(n=>n.x)),minY=Math.min(...members.map(n=>n.y)),maxX=Math.max(...members.map(n=>n.x+238)),maxY=Math.max(...members.map(n=>n.y+nodeHeight(n)));x=minX-35;y=minY-58;w=Math.max(340,maxX-minX+70);h=Math.max(220,maxY-minY+88);}else{x=(container.clientWidth/2-view.x)/view.z-280;y=(container.clientHeight/2-view.y)/view.z-180;w=560;h=360;}const group={id:M.uid(),name,color:$('group-color').value,x,y,w,h};commit(()=>{map.groups.push(group);members.forEach(n=>n.groupId=group.id);selected={type:'group',id:group.id};});selectItem('group',group.id,true);toast(t('groupCreated'));});}
function fieldDialog(node,index){const f=index===undefined?null:node.fields[index];if(!f&&node.fields.length>=100)return toast(t('fieldLimit'));openDialog(t(f?'field':'addField'),`${property('name',`<input id="field-name" required maxlength="100" value="${esc(f?.name||'')}">`)}${property('type',`<input id="field-type" list="field-types" required maxlength="50" value="${esc(f?.type||'VARCHAR')}"><datalist id="field-types">${['UUID','VARCHAR','TEXT','INT','DECIMAL','BOOLEAN','DATE','TIMESTAMP','ENUM','JSON'].map(x=>`<option>${x}</option>`).join('')}</datalist>`)}<div class="dialog-row"><label class="checkbox-row"><input id="field-pk" type="checkbox" ${f?.pk?'checked':''}>PK</label><label class="checkbox-row"><input id="field-fk" type="checkbox" ${f?.fk?'checked':''}>FK</label></div>${property('status',`<select id="field-status">${['neutral','observed','required','extension'].map(x=>`<option value="${x}" ${f?.[x]?'selected':''}>${t(x)}</option>`).join('')}</select>`)}${f?`<button id="delete-field" class="quiet danger" type="button">${t('delete')}</button>`:''}`,()=>{const name=$('field-name').value.trim(),type=$('field-type').value.trim();if(!name||!type){toast(t('emptyName'));return false;}if(node.fields.some((other,i)=>i!==index&&other.name.toLowerCase()===name.toLowerCase())){toast(t('fieldUnique'));return false;}const status=$('field-status').value,newField={name,type,pk:$('field-pk').checked,fk:$('field-fk').checked,observed:status==='observed',required:status==='required',extension:status==='extension'};commit(()=>{if(f)node.fields[index]=newField;else node.fields.push(newField);});});if(f)$('delete-field').onclick=()=>{commit(()=>node.fields.splice(index,1));closeDialog();};}
