$('project-select').onchange=e=>activateProject(e.target.value);$('new-project').onclick=createProjectDialog;$('delete-project').onclick=deleteCurrentProject;$('new-map').onclick=createProjectDialog;
$('load-example').onclick=()=>openDialog(t('exampleTitle'),`<p>${t('exampleBody')}</p>`,()=>addProjectFromMap(M.example),t('continue'));
$('add-node').onclick=()=>newNode();$('add-group').onclick=groupDialog;$('empty-add').onclick=()=>newNode();$('add-module').onclick=()=>moduleDialog();$('undo').onclick=undo;$('redo').onclick=redo;
$('map-title').onchange=e=>{const name=e.target.value.trim();if(!name){e.target.value=map.title;return;}commit(()=>map.title=name);};
