document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));renderNodes();renderEdges();});
$('columns-toggle').onchange=e=>{fieldsVisible=e.target.checked;renderNodes();renderEdges();};$('edges-toggle').onchange=e=>{edgesVisible=e.target.checked;cancelConnection();renderEdges();};
$('schema-search').oninput=e=>{search=e.target.value.trim().toLowerCase();renderNodes();renderEdges();};$('schema-search').onkeydown=e=>{if(e.key==='Enter'&&search){const node=visibleNodes().find(n=>[n.name,n.label,...n.fields.map(f=>f.name)].join(' ').toLowerCase().includes(search));if(node){view.x=container.clientWidth/2-(node.x+119)*view.z;view.y=container.clientHeight/2-(node.y+nodeHeight(node)/2)*view.z;updateTransform();selectItem('node',node.id,true);}else toast(t('noMatch'));}};
$('zoom-in').onclick=()=>zoomTo(view.z*1.2);$('zoom-out').onclick=()=>zoomTo(view.z/1.2);$('fit-view').onclick=fit;
$('toggle-modules').onclick=()=>document.body.classList.toggle('modules-open');$('toggle-inspector').onclick=()=>{if(innerWidth<=760){document.body.classList.remove('inspector-hidden');document.body.classList.toggle('inspector-open');}else document.body.classList.toggle('inspector-hidden');};$('close-inspector').onclick=()=>{document.body.classList.add('inspector-hidden');document.body.classList.remove('inspector-open');};
$('language-button').onclick=()=>{lang=lang==='es'?'en':'es';try{localStorage.setItem('schema-studio-language',lang);}catch{}translate();};
const colors={forest:['Bosque','Forest','#267454'],ocean:['Océano','Ocean','#296da3'],clay:['Arcilla','Clay','#a65539'],violet:['Violeta','Violet','#7550b4']};
$('accent-button').onclick=()=>{const menu=$('accent-menu');menu.innerHTML='';Object.entries(colors).forEach(([key,value])=>{const b=document.createElement('button');b.innerHTML=`<i class="dot" style="background:${value[2]}"></i>${value[lang==='es'?0:1]}`;b.onclick=()=>{document.body.dataset.accent=key;try{localStorage.setItem('schema-studio-accent',key);}catch{}menu.hidden=true;};menu.append(b);});menu.hidden=!menu.hidden;};document.addEventListener('click',e=>{if(!e.target.closest('.popover-wrap'))$('accent-menu').hidden=true;});
$('export-button').onclick=()=>{try{const blob=new Blob([JSON.stringify(map,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(map.title.replace(/[^\p{L}\p{N}_-]/gu,'_')||'schema-map')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast(t('exported'));}catch{toast(t('downloadError'));}};
$('import-button').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5*1024*1024)return toast(t('importLarge'));try{const next=M.validate(JSON.parse(await file.text()));openDialog(t('replace'),`<p>${t('replaceBody')}</p><p style="margin-top:12px"><b>${esc(next.title)}</b> · ${next.entities.length} ${t('nodes')}</p>`,()=>{addProjectFromMap(next);toast(t('imported'));},t('importAsProject'));}catch{toast(t('invalidMap'));}};
function renderTour(){$('tour-step').textContent=`${t('step')} ${tourStep+1} ${t('of')} 4`;$('tour-title').textContent=tr[lang].tourTitles[tourStep];$('tour-body').textContent=tr[lang].tourBodies[tourStep];$('tour-progress').style.width=(tourStep+1)*25+'%';$('tour-previous').disabled=tourStep===0;$('tour-next').textContent=t(tourStep===3?'done':'next');}
$('tour-button').onclick=()=>{tourStep=0;renderTour();$('tour-card').hidden=false;};$('close-tour').onclick=()=>$('tour-card').hidden=true;$('tour-previous').onclick=()=>{if(tourStep)tourStep--;renderTour();};$('tour-next').onclick=()=>{if(tourStep===3)$('tour-card').hidden=true;else{tourStep++;renderTour();}};
document.addEventListener('keydown',e=>{if($('app-dialog').open)return;const typing=e.target.matches('input,textarea,select,[contenteditable]');if(e.key==='Escape'){cancelConnection();$('tour-card').hidden=true;$('accent-menu').hidden=true;document.body.classList.remove('modules-open','inspector-open');return;}if(typing)return;const modifier=e.ctrlKey||e.metaKey;if(modifier&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if(modifier&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return;}if(modifier&&e.key.toLowerCase()==='d'){e.preventDefault();duplicateSelected();return;}if(modifier)return;if(e.key.toLowerCase()==='n'){e.preventDefault();newNode();}if(e.key.toLowerCase()==='g'){e.preventDefault();groupDialog();}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected();}if(e.key==='/'){e.preventDefault();$('schema-search').focus();}if(e.key==='0')fit();});
new ResizeObserver(()=>updateTransform()).observe(container);
persist();translate();requestAnimationFrame(fit);

// Optional agent tools use the editor's own state, history, validation and rendering.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const definitions=[
  {name:'read_schema_map',description:'Read the current map, including node and module IDs, fields and connections.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>copy(map)},
  {name:'create_schema_nodes',description:'Create named nodes in the current map. Nodes appear immediately and can be undone together.',inputSchema:{type:'object',properties:{nodes:{type:'array',minItems:1,maxItems:100,items:{type:'object',properties:{name:{type:'string'},module:{type:'string'},x:{type:'number'},y:{type:'number'}},required:['name','module','x','y'],additionalProperties:false}}},required:['nodes'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{
   if(!input||!Array.isArray(input.nodes)||!input.nodes.length||input.nodes.length>100)throw new Error('Provide 1–100 nodes.');
   const next=copy(map),ids=[];
   input.nodes.forEach(n=>{if(!n||typeof n!=='object')throw new Error('Invalid node.');const id=M.uid();ids.push(id);next.entities.push({id,name:n.name,module:n.module,x:n.x,y:n.y,label:'',description:'',fields:[]});});
   const valid=M.validate(next);commit(()=>{map=valid;input.nodes.forEach(n=>activeModules.add(n.module));selected={type:'node',id:ids[0]};});fit();return {created:ids};
  }},
  {name:'connect_schema_nodes',description:'Create directed connections between existing node handles. All connections are validated before any are saved.',inputSchema:{type:'object',properties:{connections:{type:'array',minItems:1,maxItems:100,items:{type:'object',properties:{from:{type:'string'},to:{type:'string'},fromPort:{type:'string',enum:M.sides},toPort:{type:'string',enum:M.sides},label:{type:'string'}},required:['from','to','fromPort','toPort'],additionalProperties:false}}},required:['connections'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{
   if(!input||!Array.isArray(input.connections)||!input.connections.length||input.connections.length>100)throw new Error('Provide 1–100 connections.');
   const next=copy(map),ids=[];input.connections.forEach(r=>{if(!r||typeof r!=='object')throw new Error('Invalid connection.');const edge=M.connect(next,r.from,r.fromPort,r.to,r.toPort);edge.label=r.label??'';ids.push(edge.id);});const valid=M.validate(next);commit(()=>{map=valid;selected={type:'edge',id:ids[0]};});return {created:ids};
  }}
 ];
 for(const definition of definitions){try{Promise.resolve(document.modelContext.registerTool(definition,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
